def get_repo_issue_stats(owner, repo, token):
    # Common GitHub GraphQL endpoint
    url = "https://api.github.com/graphql"
    headers = {
        "Authorization": f"Bearer {token}",
        "Accept": "application/vnd.github.v4+json"
    }

    # First query: Get various issue/PR counts from the repository object
    query_repo = """
    query ($owner: String!, $name: String!) {
      repository(owner: $owner, name: $name) {
        issues(states: OPEN) {
          totalCount
        }
        pullRequests(states: OPEN) {
          totalCount
        }
        bugIssues: issues(states: OPEN, labels: ["bug"]) {
          totalCount
        }
        featureRequestIssues: issues(states: OPEN, labels: ["feature-request"]) {
          totalCount
        }
      }
    }
    """
